pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 initialDeposit, uint256 secondDeposit, address actor) public {
        // Restrict values to safe ranges, keeping domain wide
        vm.assume(actor != address(0) && actor != address(this) && actor != address(c));
        initialDeposit = bound(initialDeposit, 1, type(uint128).max);
        secondDeposit = bound(secondDeposit, 1, type(uint128).max);

        // Step 1: Make an initial deposit
        vm.deal(actor, initialDeposit);
        vm.prank(actor);
        c.addToBalance{value: initialDeposit}();

        // Record balance after first deposit
        uint256 balanceAfterFirst = c.getBalance(actor);

        // Step 2: Make a second deposit
        vm.deal(actor, secondDeposit);
        vm.prank(actor);
        c.addToBalance{value: secondDeposit}();

        // Rule: final balance must equal sum of both deposits
        uint256 finalBalance = c.getBalance(actor);
        assertTrue(finalBalance == balanceAfterFirst + secondDeposit);
    }
}

