pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 preBalance, uint256 amount, address caller) public {
        vm.assume(caller != address(0));
        // Set the caller's initial balance via the payable addToBalance path with the exact preBalance,
        // but only if we can fund it.  Instead of relying on addToBalance to plant arbitrary state,
        // we use getBalance to confirm the current balance and then apply the difference via a deposit.
        uint256 current = c.getBalance(caller);
        uint256 deposit;
        if (preBalance >= current) {
            deposit = preBalance - current;
        } else {
            // Cannot reduce balance via addToBalance, so skip runs where preBalance < current.
            vm.assume(preBalance >= current);
            deposit = preBalance - current;
        }
        // Ensure the deposit does not overflow during the setup call to addToBalance
        // (both P and M allow silent overflow in addToBalance; setup must succeed without revert).
        // We assume the reference does not revert because the preBalance was chosen so that
        // current + deposit = preBalance does not overflow uint256.
        vm.assume(current + deposit >= current);
        // Provide enough ether to deposit and the fuzzed amount.
        uint256 totalNeeded = deposit + amount;
        vm.deal(caller, totalNeeded);
        vm.prank(caller);
        c.addToBalance{value: deposit}();

        // Now record the balance before the fuzzed call.
        uint256 balanceBefore = c.getBalance(caller);
        // The property: after a call to addToBalance, the new balance of the caller
        // must equal balanceBefore + amount.  The correct contract enforces this via
        // the overflow check; the buggy contract may produce a smaller value due to silent overflow.
        vm.deal(caller, amount);
        vm.prank(caller);
        c.addToBalance{value: amount}();

        uint256 balanceAfter = c.getBalance(caller);
        // Reference holds: balanceAfter == balanceBefore + amount;
        // Bug version can break when balanceBefore + amount overflows uint256.
        assertTrue(balanceAfter == balanceBefore + amount);
    }
}

