pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 preBalance, uint256 msgValue, address caller) public {
        vm.assume(preBalance < type(uint256).max - msgValue);
        vm.assume(caller != address(0));
        vm.assume(caller != address(this));
        vm.assume(caller != address(c));
        // Set preBalance by sending ether via addToBalance
        if (preBalance > 0) {
            vm.deal(caller, preBalance);
            vm.prank(caller);
            c.addToBalance{value: preBalance}();
        }
        uint256 balanceBefore = c.getBalance(caller);
        vm.deal(caller, msgValue);
        vm.prank(caller);
        c.addToBalance{value: msgValue}();
        uint256 balanceAfter = c.getBalance(caller);
        assertTrue(balanceAfter == balanceBefore + msgValue, "Balance did not increase by exactly msgValue");
    }
}

