pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address caller) public {
        // 1. Keep domain wide: only assume caller is not address(0) to avoid the zero-address edge case,
        //    and bound amount to be non-zero so the balance increase is nontrivial.
        vm.assume(caller != address(0));
        amount = bound(amount, 1, type(uint256).max);

        // 2. Set the caller's initial balance to the maximum possible to trigger overflow on the next addition.
        //    We use vm.store to set the internal mapping directly, since the contract has no external setter.
        //    This is the only way to reach a near-overflow state; no helper contract is needed because
        //    the bug manifests purely in state arithmetic, not in an external party's behavior.
        vm.store(address(c), keccak256(abi.encode(caller, uint256(0))), bytes32(type(uint256).max));

        // 3. Record the pre-balance, then execute addToBalance as the caller with the fuzzed amount.
        uint256 preBalance = c.getBalance(caller);
        vm.deal(caller, amount);
        vm.prank(caller);
        c.addToBalance{value: amount}();
        uint256 postBalance = c.getBalance(caller);

        // 4. Assertion: the post-balance must be strictly greater than the pre-balance.
        //    In the reference, the require prevents overflow and reverts, so the call would revert
        //    and the assertion is not reached (or we catch the revert). The buggy version silently
        //    overflows, making postBalance = (type(uint256).max + amount) mod 2^256, which will be
        //    less than or equal to preBalance (type(uint256).max) when amount > 0.
        assertTrue(postBalance > preBalance);
    }
}

