contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function test(address user, uint amount1, uint amount2) public payable {
        require(amount1 > 0 && amount2 > 0);
        require(user != address(0));
        require(user != address(this));

        // Fund the test contract
        require(address(this).balance >= amount1 + amount2);

        // Give user an initial balance via user (must be a callable address - we use a fresh address that can receive ether)
        // We need a payable address that will not revert on withdraw. We'll use a pre-funded EOA-like address via test parameter.
        // But we cannot deploy new contracts. Instead, we make two deposits by sending directly to C from this contract.
        // Since C's addToBalance uses msg.sender, we must call it directly.
        // We need to simulate user making deposits. Since we cannot change msg.sender to 'user',
        // we make the test contract itself the user and call addToBalance with ether.
        // The test contract address acts as 'user'.

        // Deposit amount1
        c.addToBalance{value: amount1}();

        uint balance1 = c.getBalance(address(this));

        // Deposit amount2
        c.addToBalance{value: amount2}();

        uint balance2 = c.getBalance(address(this));

        // Withdraw all
        c.withdrawBalance();

        // After withdrawal, the returned balance before withdrawal should equal the actual withdrawn amount.
        // The actual withdrawn amount is the contract's balance increase.
        // Since withdrawal sends all to this contract, we can check the balance difference.
        // But we only want one assert. We assert that getBalance returned exactly the balance before withdrawal.
        // In P, getBalance returns the stored balance, which equals amount1 + amount2 (since no prior balance).
        // In M, getBalance returns stored + 1, so balance2 = amount1 + amount2 + 1.
        // The withdrawn amount equals stored = amount1 + amount2.
        // So assert balance2 == amount1 + amount2 holds on P but fails on M because balance2 is amount1 + amount2 + 1.
        assert(balance2 == amount1 + amount2);
    }

    receive() external payable {}
}

