pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, uint256 existingBalance, uint256 sendValue) public {
        // Bound amounts to avoid overflow in the require statement and keep within admissible domain
        sendValue = bound(sendValue, 0, type(uint128).max);
        existingBalance = bound(existingBalance, 0, type(uint128).max);
        // Assume sender is not the zero address
        vm.assume(sender != address(0));
        // Set the initial balance by directly manipulating storage via a raw call is not allowed;
        // instead, we first fund sender, then send value to establish existingBalance.
        if (existingBalance > 0) {
            vm.deal(sender, existingBalance);
            vm.prank(sender);
            c.addToBalance{value: existingBalance}();
        }
        // Record the balance after initial setup
        uint256 balanceBefore = c.getBalance(sender);
        // Fund sender for the additional sendValue
        vm.deal(sender, sendValue);
        vm.prank(sender);
        c.addToBalance{value: sendValue}();
        // Read balance after the call
        uint256 balanceAfter = c.getBalance(sender);
        // General invariant: after a call to addToBalance, the balance must increase by exactly the sent value
        assertTrue(balanceAfter == balanceBefore + sendValue);
    }
