pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint8 n, address[5] calldata addrs, uint96[5] calldata vals) public {
        // Bound n to 1-5 calls to restrict loop iterations
        uint256 calls = (uint256(n) % 5) + 1;
        // Track expected cumulative balance per address (in storage we cannot mutate, so we recompute)
        for (uint256 i = 0; i < calls; i++) {
            address caller = addrs[i];
            uint256 amount = uint256(vals[i]);
            // Ensure caller is not zero address to avoid trivial reverts
            vm.assume(caller != address(0));
            // Ensure no overflow in storage addition for the reference: the require statement checks it.
            // We don't need to bound amount strictly; just provide enough ether.
            vm.deal(caller, amount);
            vm.prank(caller);
            c.addToBalance{value: amount}();
        }
        // After all calls, for each address, its balance must be <= the sum of amounts sent by that address.
        // We recompute total sent by iterating again.
        for (uint256 i = 0; i < calls; i++) {
            address caller = addrs[i];
            uint256 amount = uint256(vals[i]);
            // Calculate total sent by this particular caller across all calls (naive O(n^2) ok for small n)
            uint256 totalSent = 0;
            for (uint256 j = 0; j < calls; j++) {
                if (addrs[j] == caller) {
                    totalSent += uint256(vals[j]);
                }
            }
            uint256 balance = c.getBalance(caller);
            assertTrue(balance <= totalSent);
        }
    }
}

