pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address queryTarget, address funder, uint256 amt, uint256 fundAmt) public {
        vm.assume(queryTarget != address(0) && funder != address(0));
        vm.assume(amt > 0);
        vm.assume(fundAmt > 0);

        // Fund the 'queryTarget' under their own address to give them a balance
        vm.deal(funder, fundAmt);
        vm.prank(funder);
        c.addToBalance{value: fundAmt}();

        // Record the view result from the caller (who may be funder or someone else)
        // The bug returns msg.sender balance; correct returns queryTarget balance.
        uint256 ret = c.getBalance(queryTarget);
        uint256 expected = c.getBalance(funder);

        // The reference rule: getBalance(u) always returns userBalance[u],
        // therefore if we query 'queryTarget' we must get the same value as querying that address
        // when called by the same msg.sender. The bug returns msg.sender's balance,
        // which equals c.getBalance(msg.sender), not c.getBalance(queryTarget).
        // So the invariant is: c.getBalance(queryTarget) == c.getBalance(queryTarget) — always true.
        // But we compare against what the *correct* implementation would return by querying the mapping
        // via the same public getter with the same sender. Since the mapping is public,
        // userBalance is readable via getters; however no public getter for mapping keys exists directly.
        // Instead, we leverage the fact that addToBalance updates msg.sender's balance => we can query
        // the balance of funder as reference, but this is indirect.
        // Instead use a direct invariant: reading getBalance should be idempotent for the same argument
        // when state hasn't changed, and the invariant is: for any `addr`, getBalance(addr) returns the
        // balance of `addr`, NOT the caller's balance. To test this without inner access, we rely on the
        // fact that after funding 'funder' with 'fundAmt', calling getBalance(funder) from any sender
        // must return fundAmt. The bug will return the caller's balance (which may be 0 or fundAmt
        // if the caller is funder). So the rule: after funding 'funder' with exact fundAmt, 
        // c.getBalance(funder) == fundAmt regardless of msg.sender. The bug breaks this when msg.sender != funder.
        // To make this assertion solid, we use a separate caller distinct from queryTarget.
        // We'll check balance of funder after funding, called by funder (correctly returns fundAmt in both),
        // and balance of funder called by queryTarget (bug returns queryTarget's balance instead).
        // So invariant: c.getBalance(funder) must equal fundAmt for any caller.
        // We'll have queryTarget call getBalance(funder) and assert equality.
        vm.prank(queryTarget);
        uint256 observed = c.getBalance(funder);
        assertTrue(observed == fundAmt);
    }
}

