contract InvMutTest is Test {
    C c;
    ReentrantAttacker attacker;

    function setUp() public {
        c = new C();
        attacker = new ReentrantAttacker(address(c));
    }

    function testFuzz_property(uint256 initialBalance, uint256 reentrantDeposit) public {
        // Bound to avoid overflow in require and keep practical
        uint256 MAX = 1e36;
        initialBalance = bound(initialBalance, 1, MAX);
        reentrantDeposit = bound(reentrantDeposit, 1, MAX);
        vm.assume(initialBalance != 0);

        // Set up attacker with initialBalance in c and sufficient ETH to deposit reentrantly
        vm.deal(address(attacker), initialBalance + reentrantDeposit);

        // Attacker deposits initialBalance in C
        vm.prank(address(attacker));
        c.addToBalance{value: initialBalance}();

        // Record balances before withdrawal
        uint256 contractEthBefore = address(c).balance;
        uint256 attackerBalanceBefore = c.getBalance(address(attacker));
        assertEq(attackerBalanceBefore, initialBalance);
        assertEq(contractEthBefore, initialBalance);

        // Attacker withdraws, triggering reentrancy
        vm.prank(address(attacker));
        attacker.attack(reentrantDeposit);

        // After withdrawal, the contract's ETH balance should be exactly reentrantDeposit
        // (the re-entrant deposit), because the initialBalance was withdrawn.
        // The attacker's final balance in C should also be reentrantDeposit.
        uint256 contractEthAfter = address(c).balance;
        uint256 attackerBalanceAfter = c.getBalance(address(attacker));

        // The invariant: contract ETH equals sum of all user balances (here, only attacker has balance).
        // The bug: extra zero-setting after transfer erases re-entrant deposit balance, leaving ETH without matching balance.
        // Reference satisfies contractEthAfter == attackerBalanceAfter, mutant violates this.
        assertTrue(contractEthAfter == attackerBalanceAfter);
    }
}

