pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 deposit1, uint256 deposit2) public {
        // Keep deposits within reasonable range to avoid overflow
        vm.assume(deposit1 > 0 && deposit1 < type(uint128).max);
        vm.assume(deposit2 > 0 && deposit2 < type(uint128).max);

        address alice = address(0x1000);
        address bob = address(0x2000);

        // Alice deposits
        vm.deal(alice, deposit1);
        vm.prank(alice);
        c.addToBalance{value: deposit1}();

        // Alice withdraws - this empties her balance and, in the mutant, sends ETH to address(this) instead of to Alice
        vm.prank(alice);
        c.withdrawBalance();

        // Bob deposits
        vm.deal(bob, deposit2);
        vm.prank(bob);
        c.addToBalance{value: deposit2}();

        // Now sum of all user balances (alice + bob) should equal address(c).balance
        uint256 totalBalances = c.getBalance(alice) + c.getBalance(bob);
        uint256 contractEth = address(c).balance;

        assertTrue(totalBalances == contractEth);
    }
}

